"""Self-contained dashboard, also included in the offline zipapp."""
PAGE = r'''<!doctype html>
<html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>RPI · USBTMC Gateway</title>
<style>
:root{color-scheme:dark;--bg:#0b1119;--panel:#121d29;--line:#263546;--ink:#eaf1f8;--muted:#9cadbf;--green:#6ee7b7;--amber:#f6c96c;--red:#ff9292;--blue:#8ac8ff}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}main{max-width:1240px;margin:auto;padding:30px 24px 60px}header{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:24px}.eyebrow{font:12px ui-monospace,monospace;letter-spacing:.16em;color:var(--green);text-transform:uppercase}h1{font-size:30px;letter-spacing:-.04em;margin:5px 0}h2{font-size:18px;margin:0}h3{font-size:14px}p{margin:8px 0}.muted,small{color:var(--muted)}.badge{display:inline-block;border:1px solid var(--line);padding:4px 10px;border-radius:30px;font-size:12px;white-space:nowrap}.connected{color:var(--green)}.disconnected,.ambiguous{color:var(--amber)}.error{color:var(--red)}.toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:10px;padding:16px;background:var(--panel);border:1px solid var(--line);border-radius:12px}label{color:var(--muted);font-size:13px}input,button{font:inherit;border:1px solid var(--line);border-radius:7px;padding:9px 12px;background:#0b1520;color:var(--ink)}input{width:235px;max-width:100%}button{cursor:pointer}button:hover:not(:disabled){background:#23394d;border-color:var(--blue)}button:focus-visible,input:focus-visible,summary:focus-visible{outline:2px solid var(--blue);outline-offset:3px}button:disabled{opacity:.45;cursor:default}.primary{background:#285445;border-color:#427b65}.notice{min-height:24px;margin:12px 0 20px;font-size:13px}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:24px}.metric{border-left:2px solid var(--line);padding:4px 14px}.metric strong{display:block;font-size:24px;letter-spacing:-.04em}.metric span{color:var(--muted);font-size:12px}.section-title{display:flex;align-items:center;justify-content:space-between;margin:24px 0 12px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}article{padding:20px;background:var(--panel);border:1px solid var(--line);border-radius:12px}.card-top{display:flex;justify-content:space-between;gap:12px}.slot{font:12px ui-monospace,monospace;color:var(--muted);margin-bottom:6px}dl{display:grid;grid-template-columns:120px minmax(0,1fr);gap:6px 12px;margin:18px 0}dt{font-size:12px;color:var(--muted)}dd{margin:0;font:13px/1.5 ui-monospace,monospace;overflow-wrap:anywhere}.identity{min-height:64px;background:#0b1520;padding:10px;border-radius:6px;font:12px/1.6 ui-monospace,monospace;overflow-wrap:anywhere;margin:12px 0}.card-foot{display:flex;justify-content:space-between;gap:10px;align-items:center}.card-foot small{font-size:11px}.panel{border:1px solid var(--line);border-radius:12px;background:var(--panel);padding:18px;margin-top:16px}summary{cursor:pointer;color:var(--blue)}pre{font:12px/1.6 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;max-height:420px;overflow:auto}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px;text-align:left}th{color:var(--muted);font-weight:normal}td,th{padding:10px;border-bottom:1px solid var(--line);vertical-align:top}td{overflow-wrap:anywhere}.empty{color:var(--muted);padding:20px 0}.actions{display:flex;gap:8px;flex-wrap:wrap}footer{margin-top:24px;font-size:12px;color:var(--muted)}@media(max-width:700px){main{padding:20px 14px}.grid{grid-template-columns:1fr}header{align-items:flex-start}h1{font-size:24px}.toolbar label{width:100%}.toolbar input{width:100%}.metric strong{font-size:20px}.card-top{flex-wrap:wrap}dl{grid-template-columns:95px minmax(0,1fr)}}
</style></head><body><main>
<header><div><div class="eyebrow">Laboratorium / USB over LAN</div><h1 id="hostname">USBTMC Gateway</h1><p class="muted">Cztery przyrządy. Jeden punkt diagnostyki.</p></div><span id="connection" class="badge">Brak połączenia</span></header>
<div class="toolbar"><label>Token dostępu <input id="token" type="password" autocomplete="off" placeholder="Wklej token bramki"></label><button id="connect" class="primary">Połącz / odśwież</button><button id="identify-all" disabled>Sprawdź wszystkie · *IDN?</button><button id="download" disabled>Pobierz raport JSON</button><button id="logout">Wyczyść token</button></div>
<p id="notice" class="notice muted" role="status" aria-live="polite">Token pozostaje tylko w pamięci tej strony. Status odświeża się co 5 sekund.</p>
<div class="summary"><div class="metric"><strong id="count">—</strong><span>Urządzenia USB</span></div><div class="metric"><strong id="uptime">—</strong><span>Czas pracy usługi</span></div><div class="metric"><strong id="activity">—</strong><span>Transakcja w toku</span></div></div>
<div class="section-title"><h2>Przyrządy</h2><span class="muted">Automatyczny status · 5 s</span></div>
<section id="slots" class="grid" aria-label="Przyrządy USB"><div class="empty">Połącz się, aby zobaczyć przyrządy.</div></section>
<p class="muted"><small>Status USB nie potwierdza odpowiedzi SCPI. Test *IDN? wysyła pojedyncze zapytanie identyfikacyjne dopiero po kliknięciu. Używaj go między pomiarami.</small></p>
<div class="panel"><h2>Ostatnie transakcje</h2><p class="muted"><small>Do 40 wpisów od uruchomienia usługi. Bez treści komend i danych pomiarowych.</small></p><div id="events" class="table-wrap"><p class="empty">Brak danych.</p></div></div>
<details class="panel"><summary>Inwentarz USB i pełny status</summary><pre id="status">Brak danych.</pre></details>
<details class="panel"><summary>Szybka diagnostyka</summary><ul><li><b>Brak urządzenia:</b> sprawdź kabel, zasilanie i tryb USB „Computer”. Numer /dev/usbtmcN może się zmienić — slot używa serialu lub portu.</li><li><b>Niejednoznaczny selektor:</b> więcej niż jedno urządzenie pasuje. Doprecyzuj serial lub topologię w konfiguracji.</li><li><b>Brak uprawnień:</b> sprawdź regułę udev dla VID:PID i serialu oraz grupę labinst. Zmiana trybu USB może zmienić PID.</li><li><b>Błąd / timeout:</b> wynik ostatniej transakcji może być nieznany. Bramka nie ponawia komend automatycznie.</li><li><b>Bramka zajęta:</b> poczekaj na zakończenie transakcji. Nowe żądanie jest odrzucane przed wysłaniem komendy.</li></ul><p>Logi usługi przez SSH: <code>sudo journalctl -u labinst -n 80 --no-pager</code></p></details>
<footer>Surowy transport LAN: HTTPS /v1/transaction · jawna identyfikacja: /v1/identify · wspólna blokada USB · bez automatycznych resetów</footer>
</main><script>
const $=id=>document.getElementById(id);
const labels={connected:'USB podłączone',disconnected:'Odłączone',ambiguous:'Niejednoznaczny selektor'};
let latest=null,pending=false,testing=false,epoch=0;
function el(tag,text,cls){const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e}
function field(list,label,value){list.append(el('dt',label),el('dd',value===undefined||value===null?'—':String(value)))}
function date(value){return value?new Date(value*1000).toLocaleString('pl-PL'):'jeszcze nie wykonano'}
function controls(){ $('identify-all').disabled=!latest||testing||!Object.values(latest.slots||{}).some(s=>s.connected&&s.accessible);$('download').disabled=!latest;document.querySelectorAll('[data-identify]').forEach(b=>{const s=latest?.slots?.[b.dataset.identify];b.disabled=testing||!s?.connected||!s?.accessible}) }
function clearStatus(message){latest=null;$('slots').replaceChildren(el('p',message,'empty'));$('events').replaceChildren();$('status').textContent='Brak aktualnych danych.';for(const id of ['count','uptime','activity'])$(id).textContent='—';$('connection').textContent='Brak połączenia';$('connection').className='badge error';controls()}
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+$('token').value,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(body?65000:10000)});const data=await r.json();if(!r.ok)throw Error(data.error||('HTTP '+r.status));return data}
function render(data){
 latest=data;$('slots').replaceChildren();
 const entries=Object.entries(data.slots||{}),g=data.gateway||{};
 $('hostname').textContent=g.hostname||'Lab instruments';$('count').textContent=entries.filter(([,s])=>s.connected).length+' / '+entries.length;
 const seconds=g.uptime_seconds||0;$('uptime').textContent=Math.floor(seconds/3600)+' h '+Math.floor(seconds%3600/60)+' min';$('activity').textContent=g.active_slot||'Brak';
 $('connection').textContent='Połączono · HTTPS / API';$('connection').className='badge connected';
 for(const [name,s] of entries){
  const card=el('article',''),top=el('div','','card-top'),heading=el('div','');heading.append(el('div',name,'slot'),el('h2',s.label||name));top.append(heading,el('span',labels[s.state]||s.state,'badge '+s.state));card.append(top);
  const d=s.matches[0]||{},state=s.status,dl=el('dl','');
  field(dl,'Model USB',d.model);field(dl,'Serial USB',d.serial);field(dl,'Port / węzeł',d.topology?d.topology+' · '+d.path:undefined);field(dl,'VID:PID',d.vendor?d.vendor+':'+d.product_id:undefined);
  field(dl,'Selektor',Object.entries(s.selectors).map(([k,v])=>k+'='+v).join(', '));field(dl,'Dostęp usługi',s.connected?(s.accessible?'odczyt / zapis':'BRAK UPRAWNIEŃ'):'—');
  field(dl,'Ostatni sukces',date(state.last_ok));field(dl,'Czas transakcji',state.duration_ms===undefined?undefined:state.duration_ms+' ms');field(dl,'Transakcje / błędy',(state.transactions||0)+' / '+(state.failures||0));card.append(dl);
  const identity=el('div','','identity');identity.append(el('div','Ostatnia identyfikacja · '+date(state.identified_at),'muted'),el('div',state.identity||'Kliknij *IDN?, aby sprawdzić komunikację.'));card.append(identity);
  if(state.error)card.append(el('p','Błąd ('+date(state.last_error)+'): '+state.error,'error'));
  const foot=el('div','','card-foot'),button=el('button','Sprawdź *IDN?');button.dataset.identify=name;button.onclick=()=>identify([name]);foot.append(button,el('small','Bez zmiany nastaw'));card.append(foot);$('slots').append(card);
 }
 if(!entries.length)$('slots').append(el('p','Status trybu control dostępny poniżej w pełnym JSON.','muted'));
 const events=data.events||[];$('events').replaceChildren();
 if(events.length){const table=el('table',''),head=el('thead',''),row=el('tr','');for(const title of ['Czas','Slot / operacja','Wynik','Czas / bajty'])row.append(el('th',title));head.append(row);table.append(head);const body=el('tbody','');for(const event of events){const row=el('tr','');row.append(el('td',date(event.time)),el('td',event.slot+' / '+event.operation),el('td',event.ok?'OK':event.error,event.ok?'connected':'error'),el('td',event.duration_ms+' ms · TX '+event.tx_bytes+' / RX '+event.rx_bytes));body.append(row)}table.append(body);$('events').append(table)}else $('events').append(el('p','Brak transakcji w tej sesji usługi.','empty'));
 $('status').textContent=JSON.stringify(data,null,2);controls();
}
async function refresh(){if(pending)return;pending=true;const requestEpoch=epoch;try{const data=await api('/v1/status');if(requestEpoch!==epoch)return;render(data);if(!testing)$('notice').textContent='Status z '+new Date().toLocaleTimeString('pl-PL')+' · odświeżanie nie wysyła komend do przyrządów.'}catch(e){if(requestEpoch!==epoch)return;clearStatus('Nie można pobrać aktualnego statusu.');$('notice').textContent=e.message}finally{pending=false}}
async function identify(names){if(testing)return;testing=true;controls();const requestEpoch=epoch;const results=[];try{for(const slot of names){if(requestEpoch!==epoch)break;$('notice').textContent='Zapytanie *IDN? · '+slot;try{const r=await api('/v1/identify',{slot});results.push(slot+': '+r.identity)}catch(e){results.push(slot+': '+e.message)}}}finally{testing=false;controls();if(requestEpoch===epoch){await refresh();$('notice').textContent=results.join(' | ')}}}
$('connect').onclick=refresh;$('token').onkeydown=e=>{if(e.key==='Enter')refresh()};$('token').oninput=()=>{epoch++;clearStatus('Token zmieniony. Kliknij Połącz.');};
$('identify-all').onclick=()=>identify(Object.entries(latest.slots).filter(([,s])=>s.connected&&s.accessible).map(([name])=>name));
$('logout').onclick=()=>{epoch++;$('token').value='';clearStatus('Token usunięty.');$('notice').textContent='Token usunięty z pamięci strony.'};
$('download').onclick=()=>{if(!latest)return;const blob=new Blob([JSON.stringify(latest,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='usbtmc-status-'+new Date().toISOString().replaceAll(':','-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
setInterval(()=>{if($('token').value)refresh()},5000);
</script></body></html>'''.encode('utf-8')
